import {validateDesign,assertDesign,canonicalStringify,reviseDesign,exportCad} from './design-artifact.mjs';
import {getDesign,setDesign} from './design-state.js';
import {set,update,draftFromState} from './app.js';
import './rehearsal.js';
const $=id=>document.getElementById(id);let narratives=[];const storageKey='agent-frc-design-artifact-v1';
function status(text,error=false){$('artifactStatus').textContent=text;$('artifactStatus').style.color=error?'#ffae7c':'#a8ddcb'}
function fillMetadata(d){$('designId').value=d.id;narratives=structuredClone(d.strategy.narratives);$('narrativeSelect').replaceChildren(...narratives.map(n=>{const op=document.createElement('option');op.value=n.id;op.textContent=n.title;return op}));$('narrativeSelect').value=d.strategy.activeNarrativeId;$('narrativeText').value=narratives.find(n=>n.id===d.strategy.activeNarrativeId).narrative;$('pseudocodeText').value=d.disciplinePlans.programming.pseudocode;$('statesText').value=JSON.stringify(d.disciplinePlans.programming.states,null,2);$('fabricationText').value=d.disciplinePlans.fabrication.openQuestions.join('\n');for(const key of ['frameLengthM','frameWidthM','trackM','bumperBottomM','bumperHeightM','bumperDepthM'])$('param-'+key).value=d.design.parameters[key];status(d.id+' | revision '+d.revision+' | '+d.units+' | saved artifact state loaded')}
function capture(){window.rehearsalApi.stop();const base=getDesign(),draft=draftFromState();draft.id=$('designId').value.trim();draft.rehearsal=window.rehearsalApi.read();draft.strategy.narratives=structuredClone(narratives);draft.strategy.activeNarrativeId=$('narrativeSelect').value;draft.disciplinePlans.programming.pseudocode=$('pseudocodeText').value;draft.disciplinePlans.programming.states=JSON.parse($('statesText').value);draft.disciplinePlans.fabrication.openQuestions=$('fabricationText').value.split('\n').map(s=>s.trim()).filter(Boolean);assertDesign(draft);return canonicalStringify(base)===canonicalStringify(draft)?base:reviseDesign(base,a=>Object.assign(a,draft))}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function apply(value){assertDesign(value);setDesign(value);fillMetadata(value);const p=value.design.parameters;$('phase').value=p.phase;$('punch').checked=value.operations[0].enabled;set({x:value.frames.robot.x,y:value.frames.robot.y,heading:value.frames.robot.headingDeg,datum:value.frames.target.z,height:p.height,reach:p.reach,toolHeight:p.toolHeight,opening:p.opening});window.rehearsalApi.load(value.rehearsal);update();return getDesign()}
function guarded(fn){try{return fn()}catch(e){status('Not applied: '+e.message,true);return null}}
$('narrativeText').oninput=()=>{narratives.find(n=>n.id===$('narrativeSelect').value).narrative=$('narrativeText').value};$('narrativeSelect').onchange=()=>{$('narrativeText').value=narratives.find(n=>n.id===$('narrativeSelect').value).narrative};
$('saveDesign').onclick=()=>guarded(()=>{const d=capture();setDesign(d);download(d.id+'-r'+d.revision+'.frc-design.json',canonicalStringify(d),'application/json');status('Downloaded revision '+d.revision+'. Keep this JSON as the editable source; it includes strategy, geometry, operations, rehearsal and team sketches.')});
$('cadDesign').onclick=()=>guarded(()=>{const d=capture();setDesign(d);download(d.id+'-r'+d.revision+'.scad',exportCad(d),'text/plain');status('CAD derivative exported. Save the design JSON too: it retains narratives, sources and unresolved checks. Not fabrication-ready.')});
$('localDesign').onclick=()=>guarded(()=>{const d=capture();setDesign(d);localStorage.setItem(storageKey,canonicalStringify(d));status('Browser-local copy saved at revision '+d.revision+'. This device only; download JSON for portable backup.')});
$('loadDesign').onclick=()=>$('designFile').click();$('designFile').onchange=async()=>{const f=$('designFile').files[0];if(!f)return;try{if(f.size>2*1024*1024)throw Error('Design file exceeds 2 MiB');const value=JSON.parse(await f.text());apply(value)}catch(e){status('Not applied: '+e.message,true)}$('designFile').value=''};
for(const key of ['frameLengthM','frameWidthM','trackM','bumperBottomM','bumperHeightM','bumperDepthM'])$('param-'+key).addEventListener('change',()=>guarded(()=>update()));
fillMetadata(getDesign());try{const saved=localStorage.getItem(storageKey);if(saved){const value=JSON.parse(saved);assertDesign(value);const b=document.createElement('button');b.textContent='Restore browser copy';b.onclick=()=>guarded(()=>apply(value));$('artifactStatus').appendChild(document.createElement('br'));$('artifactStatus').appendChild(b)}}catch(e){status('A browser copy could not be validated. No design was overwritten.',true)}
window.designArtifactApi={capture,apply,canonicalStringify,validateDesign,get:getDesign};window.designArtifactReady=true;
